import{C as l,o as r,c as a,a5 as e,E as d}from"./chunks/framework.URF5zJ_R.js";const y=JSON.parse('{"title":"67 Preguntas Reales de Entrevista y Criterios de Evaluación","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"es/11_Interview_Prep.md","filePath":"es/11_Interview_Prep.md","lastUpdated":1789008202000}'),o={name:"es/11_Interview_Prep.md"},x=Object.assign(o,{setup(i){const n=[{index:"01",title:"#1 Master The 45-Minute Interview Timeline",category:"Process · Core",desc:"The golden pacing rule: Scope & Clarification (5m) -> Estimation (5m) -> High-Level Design (15m) -> Deep Dive (15m) -> Wrap Up & Observability (5m). Running out of time is the #1 failure.",meta:{Testing:"Structured communication & strict time management","Red Flag":"Jumping straight into drawing boxes without clarifying scope"}},{index:"02",title:"#15 Sharding Strategy & Partition Key Selection",category:"Databases · Advanced",desc:"The single most consequential technical decision. Weighing range vs hash partitioning, avoiding cross-shard joins, and handling query fanout.",meta:{Testing:"Horizontal scalability & data distribution","Follow-up":"How to handle the top 1% hot celebrity partition skew"}},{index:"03",title:"#20 Two Users Buy The Last Item Simultaneously",category:"Concurrency · Core",desc:"The classic inventory deduction problem. Contrasting pessimistic row locking (`SELECT FOR UPDATE`), optimistic locking with version checks, and Redis atomic Lua scripts.",meta:{Testing:"Transaction isolation levels & race condition resolution",Pitfall:"Checking inventory in memory before writing to DB directly"}},{index:"04",title:"#23 Cache Stampede & Hot Key Expiration",category:"Caching · Advanced",desc:"Preventing database collapse when a hot key expires under heavy load: distributed mutex locks, probabilistic early refresh (XFetch), and staggered random TTL jitter.",meta:{Testing:"Multi-tier cache defense against stampedes",Pitfall:"Setting identical static expiration times for all keys"}},{index:"05",title:"#30 The Myth of Exactly-Once Processing",category:"Messaging · Advanced",desc:"Honest engineering pragmatism: network unreliability means true exactly-once delivery across distributed boundaries does not exist. Real systems use at-least-once delivery + consumer idempotency.",meta:{Testing:"Distributed physical limits & deduplication design",Pitfall:"Claiming Kafka guarantees end-to-end exactly-once without caveats"}},{index:"06",title:"#35 Bulkheads & Circuit Breakers Against Cascading Failures",category:"Reliability · Advanced",desc:"The fundamental microservice rule against cascading collapse: thread pool / connection pool bulkheads, aggressive timeouts, and circuit breaker fallbacks.",meta:{Testing:"Failure domain isolation & blast radius control",Pitfall:"Sharing a single unconstrained thread pool across all dependencies"}}];return(g,t)=>{const s=l("CardGrid");return r(),a("div",null,[t[0]||(t[0]=e('<h1 id="_67-preguntas-reales-de-entrevista-y-criterios-de-evaluacion" tabindex="-1">67 Preguntas Reales de Entrevista y Criterios de Evaluación <a class="header-anchor" href="#_67-preguntas-reales-de-entrevista-y-criterios-de-evaluacion" aria-label="Permalink to &quot;67 Preguntas Reales de Entrevista y Criterios de Evaluación&quot;">​</a></h1><blockquote><p><em>Preguntas reales que los entrevistadores hacen en la pizarra, revelando qué evalúan realmente, señales de alerta y criterios de aprobación.</em></p></blockquote><hr><div class="tip custom-block"><p class="custom-block-title">💡 Regla de los 45 Minutos y Mentalidad del Entrevistador</p><p>Las entrevistas de diseño de sistemas evalúan <strong>pensamiento estructurado, criterio técnico y comunicación proactiva</strong>.</p><p><strong>Distribución recomendada de 45 minutos</strong>:</p><ol><li><strong>00 - 05m: Alcance y Aclaración</strong> — Pregunte requisitos funcionales, escala y restricciones sin esperar a que se lo indiquen;</li><li><strong>05 - 10m: Estimación Rápida</strong> — Cálculos de servilleta de QPS, multiplicadores pico, almacenamiento y ancho de banda;</li><li><strong>10 - 25m: Arquitectura de Alto Nivel</strong> — Clientes, API Gateway, servicios, esquemas de bases de datos y flujos principales;</li><li><strong>25 - 40m: Profundización y Cuellos de Botella</strong> — Particionado (sharding), colapso de caché, mensajes idempotentes y conmutación por error;</li><li><strong>40 - 45m: Observabilidad y Resumen</strong> — Métricas SLO, alertas y compromisos de diseño.</li></ol></div><hr><h2 id="📊-panel-de-control-del-banco-de-preguntas" tabindex="-1">📊 Panel de Control del Banco de Preguntas <a class="header-anchor" href="#📊-panel-de-control-del-banco-de-preguntas" aria-label="Permalink to &quot;📊 Panel de Control del Banco de Preguntas&quot;">​</a></h2><div class="stats-grid" style="margin-bottom:2rem;"><div class="stat-card"><div class="stat-icon">🎯</div><div class="stat-info"><span class="stat-number">67</span><span class="stat-label">Preguntas de Pizarra</span></div></div><div class="stat-card"><div class="stat-icon">🧭</div><div class="stat-info"><span class="stat-number">14</span><span class="stat-label">Dominios Clave</span></div></div><div class="stat-card"><div class="stat-icon">🧩</div><div class="stat-info"><span class="stat-number">8</span><span class="stat-label">Problemas LLD</span></div></div><div class="stat-card"><div class="stat-icon">⏱️</div><div class="stat-info"><span class="stat-number">45 Min</span><span class="stat-label">Modelo de Ritmo</span></div></div><div class="stat-card"><div class="stat-icon">💡</div><div class="stat-info"><span class="stat-number">100%</span><span class="stat-label">Criterios Reales</span></div></div></div><hr><h2 id="🌟-6-preguntas-de-referencia-esenciales" tabindex="-1">🌟 6 Preguntas de Referencia Esenciales <a class="header-anchor" href="#🌟-6-preguntas-de-referencia-esenciales" aria-label="Permalink to &quot;🌟 6 Preguntas de Referencia Esenciales&quot;">​</a></h2>',9)),d(s,{items:n,columns:3}),t[1]||(t[1]=e('<hr><h2 id="📋-tabla-comparativa-de-las-67-preguntas" tabindex="-1">📋 Tabla Comparativa de las 67 Preguntas <a class="header-anchor" href="#📋-tabla-comparativa-de-las-67-preguntas" aria-label="Permalink to &quot;📋 Tabla Comparativa de las 67 Preguntas&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th style="text-align:left;">Categoría</th><th style="text-align:left;">Pregunta Planteada</th><th style="text-align:left;">Qué evalúan realmente los entrevistadores</th><th style="text-align:center;">Nivel</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:left;"><strong>Proceso</strong></td><td style="text-align:left;"><strong><strong>Design [X]. You have 45 minutes.</strong></strong></td><td style="text-align:left;">Structure above all: requirements, estimation, high level, deep dive, wrap up. Running out of time is the top failure.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">2</td><td style="text-align:left;"><strong>Proceso</strong></td><td style="text-align:left;"><strong><strong>What are the functional requirements?</strong></strong></td><td style="text-align:left;">You should ask this in the first two minutes, unprompted.</td><td style="text-align:center;"><code>Foundation</code></td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;"><strong>Proceso</strong></td><td style="text-align:left;"><strong><strong>What scale are we designing for?</strong></strong></td><td style="text-align:left;">Users, QPS, data volume. Every decision downstream depends on the answer.</td><td style="text-align:center;"><code>Foundation</code></td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;"><strong>Proceso</strong></td><td style="text-align:left;"><strong><strong>Estimate the storage this needs per year.</strong></strong></td><td style="text-align:left;">Back-of-the-envelope maths with stated assumptions. Being roughly right is enough.</td><td style="text-align:center;"><code>Foundation</code></td></tr><tr><td style="text-align:center;">5</td><td style="text-align:left;"><strong>Proceso</strong></td><td style="text-align:left;"><strong><strong>Why did you choose that database?</strong></strong></td><td style="text-align:left;">Every component invites this. An unjustified choice is a lost point.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">6</td><td style="text-align:left;"><strong>Proceso</strong></td><td style="text-align:left;"><strong><strong>What is the bottleneck in your design?</strong></strong></td><td style="text-align:left;">Self-awareness. Usually the database. Say so before they do.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">7</td><td style="text-align:left;"><strong>Proceso</strong></td><td style="text-align:left;"><strong><strong>What happens when this component fails?</strong></strong></td><td style="text-align:left;">Every box you draw should have a failure story.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">8</td><td style="text-align:left;"><strong>Proceso</strong></td><td style="text-align:left;"><strong><strong>How would you know if this system was broken right now?</strong></strong></td><td style="text-align:left;">Observability. Most candidates never mention monitoring at all.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">9</td><td style="text-align:left;"><strong>Fundamentos</strong></td><td style="text-align:left;"><strong><strong>Explain CAP theorem, then tell me where your design sits.</strong></strong></td><td style="text-align:left;">Applying theory rather than reciting it.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">10</td><td style="text-align:left;"><strong>Fundamentos</strong></td><td style="text-align:left;"><strong><strong>Strong or eventual consistency here? Justify it.</strong></strong></td><td style="text-align:left;">Product judgement, not just technical preference.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">11</td><td style="text-align:left;"><strong>Fundamentos</strong></td><td style="text-align:left;"><strong><strong>What is the difference between latency and throughput?</strong></strong></td><td style="text-align:left;">Basic but frequently muddled under pressure.</td><td style="text-align:center;"><code>Foundation</code></td></tr><tr><td style="text-align:center;">12</td><td style="text-align:left;"><strong>Fundamentos</strong></td><td style="text-align:left;"><strong><strong>How do you scale this from 1,000 to 10 million users?</strong></strong></td><td style="text-align:left;">The staged scaling narrative: cache, replicas, shards, services.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">13</td><td style="text-align:left;"><strong>Fundamentos</strong></td><td style="text-align:left;"><strong><strong>Why not just use a bigger server?</strong></strong></td><td style="text-align:left;">Vertical scaling limits and cost curves. Sometimes the answer is yes.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">14</td><td style="text-align:left;"><strong>Bases de Datos</strong></td><td style="text-align:left;"><strong><strong>SQL or NoSQL for this? Defend your choice.</strong></strong></td><td style="text-align:left;">Judgement. Defaulting to NoSQL for scale without reasoning is a red flag.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">15</td><td style="text-align:left;"><strong>Bases de Datos</strong></td><td style="text-align:left;"><strong><strong>How would you shard this data? What is your partition key?</strong></strong></td><td style="text-align:left;">The most consequential decision in the design.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">16</td><td style="text-align:left;"><strong>Bases de Datos</strong></td><td style="text-align:left;"><strong><strong>Your partition key is user ID. What about the top 1% of users?</strong></strong></td><td style="text-align:left;">Hot partitions. The follow-up that catches most candidates.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">17</td><td style="text-align:left;"><strong>Bases de Datos</strong></td><td style="text-align:left;"><strong><strong>How do you add a shard without moving all the data?</strong></strong></td><td style="text-align:left;">Consistent hashing.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">18</td><td style="text-align:left;"><strong>Bases de Datos</strong></td><td style="text-align:left;"><strong><strong>A user updates their profile and sees the old version. Why?</strong></strong></td><td style="text-align:left;">Replication lag and read-your-writes consistency.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">19</td><td style="text-align:left;"><strong>Bases de Datos</strong></td><td style="text-align:left;"><strong><strong>How do you handle a schema change on a live 500 million row table?</strong></strong></td><td style="text-align:left;">Expand-contract migration. A real operational question.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">20</td><td style="text-align:left;"><strong>Bases de Datos</strong></td><td style="text-align:left;"><strong><strong>Two users buy the last item simultaneously. Walk me through it.</strong></strong></td><td style="text-align:left;">Transactions, locking, optimistic concurrency.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">21</td><td style="text-align:left;"><strong>Caché</strong></td><td style="text-align:left;"><strong><strong>Where would you add caching in this design?</strong></strong></td><td style="text-align:left;">Multiple layers: browser, CDN, application, database.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">22</td><td style="text-align:left;"><strong>Caché</strong></td><td style="text-align:left;"><strong><strong>How do you invalidate the cache?</strong></strong></td><td style="text-align:left;">The genuinely hard problem. TTL, write-through, event-driven invalidation.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">23</td><td style="text-align:left;"><strong>Caché</strong></td><td style="text-align:left;"><strong><strong>A hot key expires and the database falls over. Prevent it.</strong></strong></td><td style="text-align:left;">Cache stampede: locking, probabilistic early refresh, staggered TTLs.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">24</td><td style="text-align:left;"><strong>Caché</strong></td><td style="text-align:left;"><strong><strong>What is your cache hit rate, and what happens if it drops?</strong></strong></td><td style="text-align:left;">Whether you thought about the cache-miss path capacity.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">25</td><td style="text-align:left;"><strong>Escalabilidad</strong></td><td style="text-align:left;"><strong><strong>The load balancer is a single point of failure. Fix it.</strong></strong></td><td style="text-align:left;">Redundant balancers, DNS failover, anycast.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">26</td><td style="text-align:left;"><strong>Escalabilidad</strong></td><td style="text-align:left;"><strong><strong>How does a new server start receiving traffic?</strong></strong></td><td style="text-align:left;">Service discovery, health checks, registration.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">27</td><td style="text-align:left;"><strong>Escalabilidad</strong></td><td style="text-align:left;"><strong><strong>Traffic is 10x forecast. What breaks first?</strong></strong></td><td style="text-align:left;">Reasoning about your own design&#39;s weakest link.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">28</td><td style="text-align:left;"><strong>Escalabilidad</strong></td><td style="text-align:left;"><strong><strong>What do you turn off first under extreme load?</strong></strong></td><td style="text-align:left;">Graceful degradation and load shedding. Rarely mentioned unprompted.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">29</td><td style="text-align:left;"><strong>Mensajería</strong></td><td style="text-align:left;"><strong><strong>Why put a queue here rather than calling directly?</strong></strong></td><td style="text-align:left;">Decoupling, buffering, retry. And when a direct call is correct.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">30</td><td style="text-align:left;"><strong>Mensajería</strong></td><td style="text-align:left;"><strong><strong>How do you guarantee a message is processed exactly once?</strong></strong></td><td style="text-align:left;">Honestly: at-least-once delivery plus idempotent consumers.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">31</td><td style="text-align:left;"><strong>Mensajería</strong></td><td style="text-align:left;"><strong><strong>The consumer crashes mid-batch. What happens?</strong></strong></td><td style="text-align:left;">Offset commit strategy and duplicate handling.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">32</td><td style="text-align:left;"><strong>Mensajería</strong></td><td style="text-align:left;"><strong><strong>A message fails repeatedly. Where does it go?</strong></strong></td><td style="text-align:left;">Dead letter queues, retry limits, alerting.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">33</td><td style="text-align:left;"><strong>Mensajería</strong></td><td style="text-align:left;"><strong><strong>How do you preserve ordering while processing in parallel?</strong></strong></td><td style="text-align:left;">Partition by key. Ordering within a partition, not globally.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">34</td><td style="text-align:left;"><strong>Confiabilidad</strong></td><td style="text-align:left;"><strong><strong>The downstream service is slow. What does the user see?</strong></strong></td><td style="text-align:left;">Timeouts, circuit breakers, fallbacks. Not an infinite spinner.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">35</td><td style="text-align:left;"><strong>Confiabilidad</strong></td><td style="text-align:left;"><strong><strong>How do you prevent one slow dependency from taking down your service?</strong></strong></td><td style="text-align:left;">Bulkheads, timeouts, circuit breakers, thread pool isolation.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">36</td><td style="text-align:left;"><strong>Confiabilidad</strong></td><td style="text-align:left;"><strong><strong>Design a rate limiter for this API.</strong></strong></td><td style="text-align:left;">A standalone question in its own right. Know token bucket cold.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">37</td><td style="text-align:left;"><strong>Confiabilidad</strong></td><td style="text-align:left;"><strong><strong>An entire region goes down. What is your plan?</strong></strong></td><td style="text-align:left;">Multi-region, RTO and RPO, failover mechanics, data replication.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">38</td><td style="text-align:left;"><strong>Confiabilidad</strong></td><td style="text-align:left;"><strong><strong>How do you know your failover actually works?</strong></strong></td><td style="text-align:left;">Chaos engineering and game days. Untested failover does not work.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">39</td><td style="text-align:left;"><strong>Tiempo Real</strong></td><td style="text-align:left;"><strong><strong>How does the client learn about a new message?</strong></strong></td><td style="text-align:left;">Polling, long polling, SSE or WebSockets, with the trade-offs.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">40</td><td style="text-align:left;"><strong>Tiempo Real</strong></td><td style="text-align:left;"><strong><strong>You have 10 million persistent connections. How do you manage them?</strong></strong></td><td style="text-align:left;">Connection servers, service discovery, horizontal scaling of the WS layer.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">41</td><td style="text-align:left;"><strong>Tiempo Real</strong></td><td style="text-align:left;"><strong><strong>The user is offline when the message arrives. Now what?</strong></strong></td><td style="text-align:left;">Message store, push notifications, delivery on reconnect.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">42</td><td style="text-align:left;"><strong>Seguridad</strong></td><td style="text-align:left;"><strong><strong>How is a request authenticated across your services?</strong></strong></td><td style="text-align:left;">Gateway validation, token propagation, service-to-service auth.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">43</td><td style="text-align:left;"><strong>Seguridad</strong></td><td style="text-align:left;"><strong><strong>Where does the token get validated, and by whom?</strong></strong></td><td style="text-align:left;">Gateway versus each service, and the trade-off between them.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">44</td><td style="text-align:left;"><strong>Seguridad</strong></td><td style="text-align:left;"><strong><strong>Someone floods your API with requests. Respond.</strong></strong></td><td style="text-align:left;">Rate limiting, WAF, DDoS protection, cost controls.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">45</td><td style="text-align:left;"><strong>Seguridad</strong></td><td style="text-align:left;"><strong><strong>This data is subject to GDPR. What changes in your design?</strong></strong></td><td style="text-align:left;">Data residency, deletion, encryption, audit. Architecture is affected.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">46</td><td style="text-align:left;"><strong>Observabilidad</strong></td><td style="text-align:left;"><strong><strong>How would you debug a slow request across eight services?</strong></strong></td><td style="text-align:left;">Distributed tracing and correlation IDs.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">47</td><td style="text-align:left;"><strong>Observabilidad</strong></td><td style="text-align:left;"><strong><strong>What is your SLO for this system?</strong></strong></td><td style="text-align:left;">Turning reliability into a number with consequences.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">48</td><td style="text-align:left;"><strong>Observabilidad</strong></td><td style="text-align:left;"><strong><strong>What do you alert on, and what do you deliberately not alert on?</strong></strong></td><td style="text-align:left;">Alerting on symptoms rather than causes; avoiding alert fatigue.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">49</td><td style="text-align:left;"><strong>Costos</strong></td><td style="text-align:left;"><strong><strong>What does this system cost to run per month?</strong></strong></td><td style="text-align:left;">Commercial awareness. Very few candidates can even estimate.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">50</td><td style="text-align:left;"><strong>Costos</strong></td><td style="text-align:left;"><strong><strong>Your storage bill doubled. Investigate.</strong></strong></td><td style="text-align:left;">Retention, tiering, replication factor, unbounded log growth.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">51</td><td style="text-align:left;"><strong>Costos</strong></td><td style="text-align:left;"><strong><strong>How would you reduce this cost by half without hurting users?</strong></strong></td><td style="text-align:left;">Caching, tiering, compression, right-sizing, reserved capacity.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">52</td><td style="text-align:left;"><strong>Compromisos (Trade-offs)</strong></td><td style="text-align:left;"><strong><strong>Should this be microservices or a monolith?</strong></strong></td><td style="text-align:left;">Usually a monolith for a small team. Saying so scores points.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">53</td><td style="text-align:left;"><strong>Compromisos (Trade-offs)</strong></td><td style="text-align:left;"><strong><strong>Why not use Kafka here?</strong></strong></td><td style="text-align:left;">Recognising when a simpler queue or a direct call is correct.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">54</td><td style="text-align:left;"><strong>Compromisos (Trade-offs)</strong></td><td style="text-align:left;"><strong><strong>What would you do differently with 10x the budget? With half?</strong></strong></td><td style="text-align:left;">Whether your design is a considered choice or the only one you know.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">55</td><td style="text-align:left;"><strong>Compromisos (Trade-offs)</strong></td><td style="text-align:left;"><strong><strong>What is the simplest thing that would work?</strong></strong></td><td style="text-align:left;">Judgement. Over-engineering is as much a failure as under-engineering.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">56</td><td style="text-align:left;"><strong>Diseño de Bajo Nivel (LLD)</strong></td><td style="text-align:left;"><strong><strong>Design a parking lot system.</strong></strong></td><td style="text-align:left;">The most asked LLD question, especially at Indian companies.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">57</td><td style="text-align:left;"><strong>Diseño de Bajo Nivel (LLD)</strong></td><td style="text-align:left;"><strong><strong>Design an elevator system.</strong></strong></td><td style="text-align:left;">State machines and scheduling in object form.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">58</td><td style="text-align:left;"><strong>Diseño de Bajo Nivel (LLD)</strong></td><td style="text-align:left;"><strong><strong>Design BookMyShow or a movie ticket booking system.</strong></strong></td><td style="text-align:left;">Concurrency and seat locking at the class level.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">59</td><td style="text-align:left;"><strong>Diseño de Bajo Nivel (LLD)</strong></td><td style="text-align:left;"><strong><strong>Design Splitwise.</strong></strong></td><td style="text-align:left;">Data modelling for balances and settlement.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">60</td><td style="text-align:left;"><strong>Diseño de Bajo Nivel (LLD)</strong></td><td style="text-align:left;"><strong><strong>Design a vending machine.</strong></strong></td><td style="text-align:left;">The classic state pattern question.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">61</td><td style="text-align:left;"><strong>Diseño de Bajo Nivel (LLD)</strong></td><td style="text-align:left;"><strong><strong>Design a notification system with multiple channels.</strong></strong></td><td style="text-align:left;">Strategy and factory patterns applied cleanly.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">62</td><td style="text-align:left;"><strong>Diseño de Bajo Nivel (LLD)</strong></td><td style="text-align:left;"><strong><strong>Which SOLID principle does this design violate?</strong></strong></td><td style="text-align:left;">The standard framing for LLD feedback.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">63</td><td style="text-align:left;"><strong>Diseño de Bajo Nivel (LLD)</strong></td><td style="text-align:left;"><strong><strong>Is this design thread-safe? Make it so.</strong></strong></td><td style="text-align:left;">Concurrency at the object level.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">64</td><td style="text-align:left;"><strong>Práctica y Experiencia</strong></td><td style="text-align:left;"><strong><strong>Walk me through the architecture of a system you have built.</strong></strong></td><td style="text-align:left;">Your own work, which is where senior interviews actually go.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">65</td><td style="text-align:left;"><strong>Práctica y Experiencia</strong></td><td style="text-align:left;"><strong><strong>What is the hardest technical decision you have made?</strong></strong></td><td style="text-align:left;">Judgement and ownership. Prepare a real story with a trade-off.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">66</td><td style="text-align:left;"><strong>Práctica y Experiencia</strong></td><td style="text-align:left;"><strong><strong>What would you change about a system you worked on?</strong></strong></td><td style="text-align:left;">Self-awareness and design maturity.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">67</td><td style="text-align:left;"><strong>Práctica y Experiencia</strong></td><td style="text-align:left;"><strong><strong>Explain this architecture to a non-technical stakeholder.</strong></strong></td><td style="text-align:left;">Communication, which decides senior hiring more than depth does.</td><td style="text-align:center;"><code>Core</code></td></tr></tbody></table>',3))])}}});export{y as __pageData,x as default};
